export const TRACKS={'menu-tower':'menu-tower','menu-den':'menu-den','menu-survival':'menu-survival','menu-pvp':'menu-pvp','menu-gacha':'menu-gacha','menu-conquest':'menu-conquest',invocation:'invocation',home:'sanctuary',tower:'sanctuary',pvp:'sanctuary',collection:'sanctuary',team:'sanctuary',inventory:'sanctuary',friends:'sanctuary',profile:'sanctuary',gacha:'summon',survival:'survival',arena:'battle',battle:'battle',den:'den',afk:'menu-pokeclick',conquest:'conquest',storm:'storm',cosmic:'cosmic',forest:'forest',victory:'victory',defeat:'den'};
export class MusicPlayer{
 constructor(g){this.g=g;this.scene='home';this.unlocked=false;this.holds=new Set();this.current=null;this.retiring=null;this.activeTrack=null;this.abort=new AbortController();const signal=this.abort.signal;const unlock=()=>this.unlock();document.addEventListener('pointerdown',unlock,{signal});document.addEventListener('keydown',e=>{if(e.code==='KeyM'&&!/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)&&!e.ctrlKey&&!e.altKey){e.preventDefault();this.toggle()}else this.unlock()},{signal});document.addEventListener('visibilitychange',()=>{if(document.hidden){this.current?.pause();this.retiring?.pause()}else this.refresh()},{signal})}
 unlock(){if(this.unlocked)return;this.unlocked=true;this.refresh()}
 setScene(scene){this.scene=scene;this.refresh()}
 refresh(){this.updateButton();if(!this.unlocked||!this.g.state.settings.music||document.hidden||this.holds.size){this.current?.pause();this.retiring?.pause();return}const key=TRACKS[this.scene]||'sanctuary';if(this.activeTrack===key&&this.current){this.current.play().catch(()=>{});return}this.switchTo(key)}
 switchTo(key){cancelAnimationFrame(this.fade);this.retiring?.pause();const old=this.current;this.retiring=old;const next=this.current=new Audio('assets/music/'+key+'.wav');this.activeTrack=key;next.loop=true;next.preload='auto';next.volume=0;next.play().then(()=>{if(next!==this.current){next.pause();return}const start=performance.now(),oldVolume=old?.volume||0;const frame=t=>{if(next!==this.current)return;const p=Math.max(0,Math.min(1,(t-start)/750)),volume=this.g.state.settings.musicVolume;next.volume=this.g.state.settings.music?volume*p:0;if(old)old.volume=oldVolume*(1-p);if(p<1&&!document.hidden)this.fade=requestAnimationFrame(frame);else{old?.pause();if(this.retiring===old)this.retiring=null;next.volume=this.g.state.settings.music?volume:0}};this.fade=requestAnimationFrame(frame)}).catch(()=>{if(next!==this.current)return;if(next.paused&&(this.holds.size||document.hidden||!this.g.state.settings.music)){old?.pause();return}this.activeTrack=null;this.current=null;old?.pause()})}
 hold(reason,paused){if(paused)this.holds.add(reason);else this.holds.delete(reason);this.refresh()}
 toggle(){this.g.state.settings.music=!this.g.state.settings.music;this.g.save();this.unlock();this.refresh()}
 setVolume(value,persist=true){this.g.state.settings.musicVolume=Math.max(0,Math.min(1,Number(value)||0));if(this.current)this.current.volume=this.g.state.settings.music?this.g.state.settings.musicVolume:0;if(persist)this.g.save()}
 updateButton(){document.querySelectorAll('[data-act="toggle-music"]').forEach(b=>{b.setAttribute('aria-pressed',String(this.g.state.settings.music));b.setAttribute('title','Musique '+(this.g.state.settings.music?'activée':'désactivée')+' · M');if(b.dataset.musicIcon!==undefined)b.textContent=this.g.state.settings.music?'♫':'♪';else b.textContent=this.g.state.settings.music?'Activée':'Désactivée'})}
 destroy(){this.abort.abort();cancelAnimationFrame(this.fade);this.current?.pause();this.retiring?.pause()}
}
